class DualLogicNetwork(nn.Module):
    def __init__(self):
        self.logic_rules = LogicNetwork(...)  # Shared
        self.auto_head = nn.Linear(I, 9*3)    # Next state
        self.rl_head = nn.Linear(I, 9)        # Q-values per action

    def forward(self, state, mode='both'):
        # Shared logic processing
        captured_vars = self.logic_rules(state)

        if mode in ['auto', 'both']:
            next_state = self.auto_head(captured_vars)
        if mode in ['rl', 'both']:
            q_values = self.rl_head(captured_vars)

        return next_state, q_values

